using System.Text;
using Microsoft.EntityFrameworkCore.Storage.ValueConversion;

namespace ID_Indetails.api.Data;

/// <summary>
/// Stores an enum as its snake_case name (<c>ProjectStatus.Active</c> → <c>"active"</c>,
/// <c>EditWindow.OneDay</c> → <c>"one_day"</c>), so values in the database are readable and
/// match the CHECK constraints generated by <see cref="SnakeCaseEnum.CheckSql{TEnum}"/>.
/// </summary>
public sealed class SnakeCaseEnumConverter<TEnum>()
    : ValueConverter<TEnum, string>(
        value => SnakeCaseEnum.ToDb(value),
        value => SnakeCaseEnum.FromDb<TEnum>(value))
    where TEnum : struct, Enum;

public static class SnakeCaseEnum
{
    public static string ToDb<TEnum>(TEnum value) where TEnum : struct, Enum
        => ToSnakeCase(value.ToString());

    public static TEnum FromDb<TEnum>(string value) where TEnum : struct, Enum
    {
        foreach (var candidate in Enum.GetValues<TEnum>())
        {
            if (ToDb(candidate) == value)
            {
                return candidate;
            }
        }

        throw new InvalidOperationException(
            $"'{value}' is not a stored value of {typeof(TEnum).Name}.");
    }

    /// <summary>All stored values of an enum, in declaration order.</summary>
    public static IReadOnlyList<string> Values<TEnum>() where TEnum : struct, Enum
        => Enum.GetValues<TEnum>().Select(ToDb).ToList();

    /// <summary>SQL for a CHECK constraint limiting <paramref name="column"/> to the enum's values.</summary>
    public static string CheckSql<TEnum>(string column) where TEnum : struct, Enum
        => $"`{column}` IN ({string.Join(", ", Values<TEnum>().Select(v => $"'{v}'"))})";

    private static string ToSnakeCase(string name)
    {
        var sb = new StringBuilder(name.Length + 4);
        for (var i = 0; i < name.Length; i++)
        {
            var c = name[i];
            if (char.IsUpper(c) && i > 0)
            {
                sb.Append('_');
            }
            sb.Append(char.ToLowerInvariant(c));
        }
        return sb.ToString();
    }
}
